package com.zheng.algorithm.leetcode;

import com.zheng.algorithm.leetcode.tree.TreeNode;

/**
 * 100. 相同的树
 * <p>
 * 给你两棵二叉树的根节点 p 和 q ，编写一个函数来检验这两棵树是否相同。
 * <p>
 * 如果两个树在结构上相同，并且节点具有相同的值，则认为它们是相同的。
 * <p>
 * 示例 1：
 * <p>
 * 输入：p = [1,2,3], q = [1,2,3]
 * 输出：true
 * 示例 2：
 * <p>
 * 输入：p = [1,2], q = [1,null,2]
 * 输出：false
 * 示例 3：
 * <p>
 * 输入：p = [1,2,1], q = [1,1,2]
 * 输出：false
 * <p>
 * 提示：
 * <p>
 * 两棵树中节点的数量处于范围 [0, 100] 内
 * -10^4 <= Node.val <= 10^4
 *
 * @author zheng
 * @date 2023/1/10
 */
public class LeetCode100 {

    public static void main(String[] args) {
        TreeNode p = TreeNode.buildTree(new Integer[]{1, 2, 3});
        TreeNode q = TreeNode.buildTree(new Integer[]{1, 2, 3});
        System.out.println(isSameTree(p, q));
    }

    public static boolean isSameTree(TreeNode p, TreeNode q) {
        if (p == null && q == null) {
            return true;
        }
        if (p == null || q == null) {
            return false;
        }
        if (p.val != q.val) {
            return false;
        }
        return isSameTree(p.left, q.left) && isSameTree(p.right, q.right);
    }
}
